    "originalText": "神仙经曰，凡欲学禁，先持知五戒十善八忌四归，皆能脩治此者，万神扶助，禁法乃行。五戒者一曰不杀、二曰不盗、三曰不淫、四曰不妄语、五曰不饮酒嫉妒。十善者一济扶苦难、二行道见死人及鸟兽死者皆埋之、三敬重鬼神、四不行杀害起慈悯心、五不怜富憎贫、六心行平等、七不重贵轻贱、八不食酒肉五辛、九不淫声色、十调和心性不乍嗔乍喜。八忌者一忌见死屍、二忌见斩血、三忌见产乳、四忌见六畜产、五忌见丧孝器泣、六忌抱小儿、七忌共女人同茥、八忌与杂人论法。四归者一不得着秽污不净洁衣服即神通不行、二不得恶口咒诅骂詈、三不得共人语诈道称圣、四不得饮酒食肉杀害无道、又云不得秽处诵禁文、又云不得与不信人行禁、又不得向人说禁法、又不得秽污手执禁文、又不得与杂人諠戏、又不得轻说神明、又不得嗔打六畜及人不得乘车马。有犯此满三事，则禁道不行，能不犯者，其禁大验。经曰，若履城邑污秽者当用此方。竹叶（拾两）、桃白皮（肆两）、柳白皮（肆两）。右三味，以水壹石贰斗煮之一沸，去滓，浴身，百秽消除，又辟温瘴疮疡，此法，天仙下游既返之日，未尝不用此方解秽也，至於符水咒漱及外舍之近术皆不及此方，若能常用此汤澡浴者益佳，惟不可洗目也。紫微王夫人敕水洗目得清净法浊不秽形，死不妨生，摩掌蕤目三遍，令我长生，青龙在吾左，白虎在吾右，朱雀在吾前，玄武在吾后，神禁敕水除尘垢急急如律令",
