    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "神仙经曰，阳道强坚而易歇，阴道微软而久长，圣人闭口，万物可藏，回转清白，改易阴阳，应言不言，神明相传，应语不语，神明相与，故万法闭口藏身之禁法流行五藏神明，众人游戏而我独住，众人浩浩而我独静，众人言说而我独嘿，此行禁之道毕矣。仙经曰，凡受禁之法，当先齐戒百日，精心不行淫欲，惟得清净沐浴着鲜净衣，口常不出恶言骂詈，精思静念，勿生异想，一如前章仍更七日之中，闭口不共人语，乃可受之。正月一日、三月三日、五月五日、七月七日、九月九日、三年之中三遍於此月日受之，并一心持斋戒不犯则行禁其验如神。正月一日受法正月一日平旦寅时，清净澡漱，在无人清净之处，着鲜净衣，不得令人辄见，烧众名香正面向东禹步三匝，勿回转长跪读启度文曰，上启三师神童玉女天医卢医一切诸师太上老君诸仙神王日月五星二十八宿北斗三台诸神仙官属诸大神王咸知，弟子某甲受持符禁之法，愿济拔众生苦难，除毒消邪，辟却奸恶万事，如敕急急如太上老君律令。都受禁文曰想东方木禁在吾肝中、想南方火禁在吾心中、想西方金禁在吾肺中、想北方水禁在吾肾中、想中央土禁在吾脾中。想左青龙右白虎，前朱雀后玄武，天师禁驾无事不苦，东王公西王母道吾禁有随当止，急急如太上老君律令讫，还诵所得禁文各三遍礼一十二拜，仍更七日勿共人作一言及恶骂詈等语，七日勿洗手。三月三日受法三月三日平旦寅时，至东流水上，正面向东立，端心正意读前启度文如正月法，并启江河四渎一切水官四海大龙正，愿知弟子某甲受持禁法愿大神王立契讫，诵所得禁文各六遍礼九拜。五月五日受法五月五日正中午时，在静处烧香，正面向南立，读启度文讫，诵所得禁文各三遍礼十二拜。七月七日受法七月七日鸡鸣丑时，在静处烧香，正面向西立读启度文讫，诵所得禁文各三遍礼七拜。九月九日受法九月九日人定亥时，在静处正面向北立，盆盛水口衔刀读启度文，投香火长跪，诵所得禁文，各三遍礼九拜，此五日处法，用一如正月法，惟所向方及拜数不同耳。太白仙人受法四月一日，斋戒至八日，立道场，四面悬幡，盖烧香然灯，启醮五方五帝五方禁师五方吞精啖毒夜叉神王，愿知弟子某甲受持禁法咒讫，诵所得禁文各三遍，七日斋戒。同力受禁法候初雷时举目看雷，右手把刀以左手摩之，咒曰，助我行禁振声如雷吼，万毒伏闭气，待雷声尽讫，七日斋戒不出言，一本云候初雷时，眼所见物，随便把取唱言声如雷，万邪皆怖畏，待雷声尽乃弃之（一云口衔刀手捉大斧摩之言口如毒手如毒声如雷吼云云）。神仙王受禁法候鷰初来时，仰头看之，以手按地云，口如毒，以鷰去不见乃止，此等洁净斋戒，一如正月不别，乃至七日不洗手。天帝太一受禁法初受禁时，在寂静无人之处敷坐，设案烧香，正面向北闭口并足正立，左手持刀，依式思存，青龙在左，白虎在右，朱雀在前，玄武在后，北斗七星覆头上柄指前，次思东治大禁师愿持兵万石赵候骠骑大将军苏平南公八部将军七十二禁师陈师赵师直符小吏直日童子护直今日，不得以左为右，以前为后，若有倒错，即依使者法律科罪之，急急如律令",
