    "originalText": "三遍咒讫，以水洗目，并噀四方上下，余水自饮之，洗腹内令净，想又读前启度文然后长跪诵所得禁文各三遍讫礼四方各再拜即成神验，刀子水盆不得用曾经酒肉五辛者。又一法正月一日东方明星出时洗浴，在清净无人之处，白茅为藉置坐设案烧香火，并花水洗面目，正面东向并足立，先举左手呼青龙，次举右手呼白虎，前行呼朱雀，后行呼玄武讫，依前左手持刀次第思神师日符禁同法，更无别法也，若欲受符印者，以帛若袋子盛挂着左手指句之，而擎水盆闭气禹步，依法次第咒请有效也，。七星受咒法正月一日、三月三日、五月五日、七月七日、九月九日。先以香汤洗浴，取东流水未经用瓦器盛之，以诵所得禁文咒一遍，受人自洗浴於旷野无人之处，以净草为坐，以瓦器盛水七盏，作七星形北向云，谨启七圣真君，弟子某乙愿持禁法，禁断邪恶鬼毒之气，救理人民伏愿降真气流布臣身，令臣所行符禁应声除差，应手除愈，次第饮前件水各少许余洗手，不得手捻不净之物即有大验（一云七佛咒法下又有一观自存咒法今并不取）。黄帝越禁受法黄帝曰，凡受符禁者皆清净斋洁百日，不得近死亡产乳房室，三年之中三度，正月一日、三月三日、五月五日、七月七日、九月九日、以夜众星之下，置神座设案烧香，盆盛水临刀北面叩齿捻三师目，次第思神讫禹步三匝，长跪读启度文，又诵所得禁文各三遍神验，水盆不得用曾盛酒肉五辛者临欲越时朱书帛素上，左手持之捻目阴诵咒之，欲行禁时闭气朱书帛素上，右手持之捻目阴诵咒之。杂受禁法",
