    "originalText": "正月一日日未出寅时、三月三日寅时、五月五日午时、七月七日丑时、九月九日寅时（一云丑时）、正月受一年用、三月受一春用、五月受一夏用、七月受一秋用、九月受一冬用。右年年常依此日受之法，不得饮酒食肉五辛芸薹乳酪酥蜜，心如药王药上愿救护一切众生，不作艰难，不求财物，但作此心下口即差，万不失一，受法用前月日，先以清净井花水沐浴，上下衣服一切鲜净清斋七日，至其日先以井花水澡浴漱口，烧香礼五方五帝各五拜讫，正面向东烧香端立，净器盛井花水置傍，诵所得禁文各二七遍讫，口含水仰噀五方承取洗手面讫，向东方吸青气想入口中七吸，次向南方吸赤气，次向西方吸白气，次向北方吸黑气，次吸中央黄气，皆作七吸入腹想讫，更礼五方各五拜讫，后作两月持斋戒作得禁想，不得作一切诸恶行受讫即成禁法，器物不得用曾经盛酒肉五辛者。受禁肿法古塚北桑树阴内有艾者，五月五日平旦日未出时，从塚北向南步取五十四步，至艾作禹步北斗七星讫，还闭气将取艾弃拭手使汁入手中，七日勿洗手，持斋过七日以外即成禁五十四步之中摽记使分明，一步七尺，登取艾时，面向西方咒，愿我此手一切痈肿，一切诸毒，乃至一切病手着即差，作法讫，还，勿反顾，受时以五月四日作斋摽记，步数，亦四日使记，先从艾东置魁，因北向为尾向北五十四步作摽记，五日旦从北向南步之作法了斋，至十一日上桑树，在塚北从地三尺於塚上生者佳，亦於四日在塚东宿，五日旦即作法禹步法，闭气握固，若治病时作想此手作热铁又想前人病如雪手着病即散，又治病时常在病人生气上若病人头面上有浮肿，不得顿治使尽即伤人，必当留少许明日更治，此去大业六年，琅邪郡莒县令梁阔送擅持山善寂道场灵法师所行，神验不传。受禁疟法候鷰初来时，以纸一张，浓点笔於纸上，望鷰与点，鷰没乃止，后若疟病人来，向云我患疟即语我与你治，你但去阴押取一点，塞壁孔中即愈，又法正月元日呼牛马时火下将笔闭气多书纸上作鬼字气尽乃止，虐病欲发时，押取一鬼字与吞之即差。受禁肿都禁法正月元日东方动时，以净席一领於寂静无人之地，以井花水沐浴漱口三遍，手持香炷礼五方五帝君，咒愿曰，弟子某甲今日受天神咒愿救一切众生苦，四方各礼三拜讫想，东方青气入口掎七咽，南方赤气，西方白气，北方黑气，中央黄气等各七咽讫，向南东方闭气诵咒各七遍，七日持斋戒咒曰天之所圆地之所方，受天神符可以长生，二十八宿其色亭亭，五色变化与符合并，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
    "imgStatus": "原刻影像待补（人卫/元大德本影刻）",
