    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "须紫檀杷刀子，以刀杷按肿上，其肿疼痛用前禁文，若不疼痛用此禁禁之，然此二禁皆是正禁肿文，凡是恶肿皆用此二文，其大肿日别四五度，禁五日差，小者当日差。大总禁法咒曰，朝日不良，为物所伤，上告天公，下告地皇，地皇夫人，教我禁疮，仙人持水，玉女持浆，一唾止毒，二唾止疮，三唾巳后，平复如常，天雷马鸣疮亦不惊，天雷地动，疮亦不恐，皮相连肉相当，不疼不痛不肿不脓，急急如律令",
