    "detail": "此段为禁法修习的纲领性文字（戒律、受法时辰、禹步闭气掌诀等），非针对某一病症的具体禁咒，是理解《禁经》体系的方法论背景。",
    "originalText": "用法以刀子一枚，先吸一口水捻盐着口中和水噀病上，若小儿惊恐，当噀地上二三过，駃唾病上，以口附近病上诵禁每一遍三唾，每七遍，一遍盐水嗽口，三七遍成一禁也，若不差，多加遍数，取差为限，若百遍不差者，此病大重，不可救也慎勿与治。禁时气病法头痛以刀隐痛处，唾禁如前缘，但有患疼痛处，皆用刀背隐而禁之，若金疮从高堕下，六畜狼虎毒蛇所伤，手足卒挛躄，凡百一切痛苦不如意处，并用此法禁咒之，悉得除愈，不可具载，男女并得受持。论曰，此之杂法，由禁师不能具美大法，所以须受轻法，易者约者，若受大法此亦不须。禁法大例",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
