    "summary": "唐《千金翼方·禁经》所载「咒法」，属禁法大例类禁法，文中记有持刀、营目、捻掌诀、叩齿等做法。",
    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "论曰，用禁大例，诵禁文必不得出声，令自耳闻声，若闻之咒即禁法不行，行之无益，慎之慎之，受禁之时，不得令人畜等一切见之见之即不成，受法时，刀及水盆，皆不得曾经酒肉五辛用者。神仙经曰，对治禁万病击同类。逢水难土王击之、逢土难木王击之、逢刀难阳精击之、逢鬼难桃汤击之逢虎难五常气击之，万病击同类对治，皆持刀持桃持火持鑑持水持绳持药持符持戟持弓持箭持弩持食持坐持粉持意持神持想持气持画持石持土持盐持幡持脂持肉持血持麵持金持玉持印，故其法皆禁击之，所须用禁之法，有请有告有祭，有害（善神即饮食祭之住之恶鬼即茢之却之）有杀有畏，有爱有喜有恶有死有走有住有灭是故对治用时各各条列。仙经曰，用禁有六法，一牙齿禁意存气至牙齿，二营目禁，开一目闭一目，三意想禁，存意以去想诸疾以除，四捻目禁，谓手上有一十五目，五气道禁，谓吹呼呵嘘嘻呬，六存神禁存诸神在，以食醮祭之，感天灵气至，又鸣天鼓叩齿是也。凡为人请疗疾出门三步咒曰。天杀黄黄，地杀正方，千鬼万神，谁复敢藏飞步一及，百鬼灭亡，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
