    "lineage": "COMMON",
    "summary": "《禁经》禁法大例篇关于持禁斋戒、受法、禹步掌诀等方法论的记述。",
    "detail": "此段为禁法修习的纲领性文字（戒律、受法时辰、禹步闭气掌诀等），非针对某一病症的具体禁咒，是理解《禁经》体系的方法论背景。",
    "originalText": "三嘘三叱，以刀右搅三回，以右足跟蹴地三下，含水四方喷之，及喷病人上，尽令清洁，然后按法思神行禁，又存气至牙齿令住闭一目，存意巳去即捻目，然后用存七星在其顶上，存青龙白虎朱雀玄武来护身，存大神在其前后五星，存之腹内，吐气存如云击彼处令如徐行，行步法乾坤，如此行，按即外邪不入五藏神明自通，仍皆须审之，万不失一，又法欲向病人家当须存想作白虎吐火，烧病人家屋舍皆令荡尽，又作龙舐病人身肉令尽，还作充满悦怿，然后用气急治之，欲击物，一一皆如是此令行禁神明万物皆神效验须精审之，若唾热病，以冷气吹之二七，然后禁之，若唾冷病，以热气呵之二七然后禁之，三唾之后行禁，禁后三唾乃放之。仙经曰，受符禁同法，先当脩身洁已安魂定魄，口勿妄言，洁斋百日，可致神仙，避逆恶气，除灭灾祥，可以长生。掌诀法",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
    "imgStatus": "原刻影像待补（人卫/元大德本影刻）",
