    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "禁疟鬼法先取一平塼，令病人在无人处不得见人，大从月建向月破，以砖磨地令平，以手按塼四角使不动还以手发塼立，在前可塼下书北斗，傍置三台，外尽孤虚，直取旬孤虚，其北斗中画作小鬼患人姓名年几，置下在斗柄中，咒曰。小么字某甲年若干，你从台入斗疟鬼断后，若患人时，头上先下若非患人时，头下先下若无逆顺，平下塼讫，若患人日一发以手二七下打塼，若隔日发三七下打塼，三日一发以上四七下打塼讫，取塼傍土拥塼，即复左手取一把土散塼上而去慎勿反顾大验。又以故笔画六尺方中，画作北斗，形皆以北斗，相应其魁衡必令开门，以身左行向斗魁闭气并足俱前而立咒曰。小鬼吾今出天门，入地户不得从我去住，出建上之门，急去不得反顾，即差，三七日不发，与人治患还得此患必用此治欲令患人还发，二七日内发之法。还取患人发以足，蹴导咒曰。小鬼尔从斗入台，疟疾还回，即发。敕禁疟鬼法书桃枝一尺，欲发即用，噀病人面诵咒文二七遍，系着头底，天姓张，地姓皇，星月字长，日字紫光，南山有地，地中有虫赤头黄尾，不食五榖，只食疟鬼，朝食三千，暮食八百，少一不足，下符请索语你速去，即得无殃，汝若不去，縳送魁刚，急急如律令",
