    "originalText": "又法取东壁土三丸，向井东置一丸，三咒曰赫赫洞洞，日出东方，上有崑崙之山，下有清泠之泉，某甲患某处上有发痈，土入井中，天公当烂，石痈当散，七星北斗光，织女教我方唾，汝急出不得留藏，急急如律令",
