    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "禁注法吾从天南来至北，食盐三斛，饮水万千，经江量海，手捉丘山，口含百毒，心怀蚰蜒，唾天须转，唾地陷穿，唾石碎裂，唾火灭烟，唾鬼即死，唾水竭渊，东方之注自名医，入人体中注心根，神师咒注注灭门，南方之注自名青，入人体中注百糗，神师咒注注即易，西方之注自名摇，入人体中注脊腰神师咒注注即消，北方之注自名雌入人体中注心脾，神师咒注注即移，中央之注自名雉，入人体中注十指，神师咒注注即死，四方之注尽巳亡，惟我五藏永安强，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
