    "medicine": "盐",
    "ritualSteps": null,
    "pseudonym": null,
    "modernMedicine": "此为古代医籍中的祝由疗法，古人以禁咒配合禹步、闭气等仪式。现代医学对疟疾、瘟疫、蛊毒、遁注(疑为传染病/寄生虫/急腹症等)有明确诊疗，发热、疫病、腹痛等务必尽快就医检测治疗，勿以禁咒替代。",
