    "originalText": "此咒当晨朝日初出时，遣病人净洗手面，向东方至心礼太山讫，更以水洗手至心合掌正西立，师当在东，正当病人，面向南立，以此咒之七遍便愈，若不愈者，明晨更如是咒之，不过三朝，无不愈者。禁唾飞尸入腹急切痛法请天上飞龙穷奇白虎，眼如明星，腹如建鼓，齐功叩齿，主食恶鬼，入食飞尸，出食殃魅，人生於天，吞气受道，身形之中，非汝所处，形中五部各有所主，肝为青龙，肺为白虎，心为朱雀，肾为玄武脾为中府，主御四方上有真人赤城童子，下有咸池青腰玉女，各守部界，不得留住方名道人，教来治汝，头则法天身法北斗，手为魁刚，口为金斧，主授六甲，直神辅汝，何鬼不出，何尸不走，急急如律令",
