    "summary": "唐《千金翼方·禁经》所载「咒法」，属禁邪病类禁法，文中记有捻掌诀、朱书等做法。",
    "detail": "原典将禁咒、禹步、闭气、捻掌诀、唾噀等视为一体的疗病/禳除仪式。本条照录原文，仅作文献事实陈列；其中\"大验/即愈\"等是古人的灵验主张，不等于现代医学疗效。",
    "originalText": "凡鬼邪着人，或啼或哭，或嗔或笑，或歌或咏，称先亡姓字，令人癫狂，有此状者，名曰鬼邪，唯须伏鬼，遣之乃差，治之法正发时，使两人捻左手鬼门鬼市，两人捻右手如左手法，鬼门者掌中心是鬼市者腕后厌处是伸五指努手力则厌处是腕后者大指根两筋中间是，一捻之后，不得蹔动，动鬼出去，不得伏鬼，又不得太急，若太急则捻人力尽，力尽即手动手动即鬼出，亦不得太缓，若太缓复不能制鬼，惟须以意消息令缓急得所，复使两人投淐子剌两肩井中，缓急如鬼门鬼市法，以鬼伏为限，若不伏，稍稍急剌，若鬼伏即稍轻剌之，若病人是丈夫肥壮者，则急剌之，量人之强弱消息以意，若淐尖利以布物裹之，勿令人伤，亦须诵咒，必臣伏如状貌中有似伏状不复相骂，下情求首叩头求去，遣一人捉咒师自问鬼之姓名，住何州县乡里，年几贯属，伴侣几人，又问来意有所须为何事来，一依病人口笔写之，若其臣伏，叩头求去，不敢更住者，且停剌肩井等，依其所须备觅发遣之，须食与食须金银车马，即釆画人马像，金银綵帛，随其形貌悉尽作之绢帛以白纸作，金以栀子染之若是远来之鬼须给过所者亦即给之，即日早发遣，或待后发遣亦得，送鬼之时，须桃符一板，长七寸阔三指，综綖一条长七寸，以朱书板，上着年号月朔日子，鬼之乡里姓名年几，从人头数，告五道大神，河伯将军，上件鬼某甲等，在我家中作如此罪过，捉获正身，所索之物，并巳具给发，遣速出去，不得久停不得久住，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
