    "originalText": "禁蛇法押蛇头咒曰寅加卯寅加卯三遍即愈，若欲发蛇毒，押蛇尾到诵之卯加寅卯加寅蛇毒即发剧，一注螫右相押左手，自余皆同，又法庚寅卯，庚寅卯三遍即愈，若欲令发云，卯寅庚，卯寅庚即发，又法辰生巳，辰生巳，蛇毒即止，三遍即愈，欲令发者云，巳生辰，巳生辰即发。禁蛇法一名蛇，二名蟾，三名蝮，居近野泽，南山腹蛇，公青蛇，母黑蛇公字麒麟蛇，母字接肋犀牛角麝香牙鹳鹊觜野猪牙啄蛇腹腹熟啄蛇头头烂蜈蚣头鸩鸟羽飞走鸣唤，何不急摄汝毒，还汝本乡江南畔，急急如律令",
