    "originalText": "禁蜂毒（捻峰目左营目闭气向王为之）。东方青毒还东方、南方赤毒还南方、西方白毒还西方、北方黑毒还北方、中央黄毒还中央。黄蜂颺颺，黑蜂奕奕，王有小女，嫁与河伯吾有铜掌铁指，押汝便死，汝是小虫，何不速去毒阴，吾曰大鸟敷翅，三千八万里不得张口，汝应是死，急急如律令",
