    "originalText": "作此法时，於室中净扫地，穴前遍扫之，桃枝以茅草索结杖中腹以三箇穴立呼之矣。初越集鼠法初越时以香汤浴身，洒室中及庭前地讫，用三盆三家浆粉，以刀子横着盆上，以灰匝之，以笔一管，去盆三尺着地，所有穴前皆安，灰广一尺，上作子字，一云穴上紫字，乃咒曰。北斗三台，招摇所录，天李自形，必归所属寄食附人，穿穴我屋，胡为杨时，饭食欲熟急敕鼠王，召集眷属，大鼠小鼠并须来食，侧立单行，洗洫心垢，伏罪勿走，汝父小奚，汝母幽方，汝兄阿特，汝弟阿当，汝妹仆姜，室家相将归化坐傍固告敕汝莫以旧为常，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
