    "originalText": "咒曰诺诺睾睾，左带三星，右带三牢，天翻地覆，九道皆塞，使汝失心，从此迷惑，以东为西，以南为北，人追我者，终不可得，明星北斗，却闭千里，六甲反张，不避祸殃，乘车追我，折其辕轴，乘马追我，掩其两目，步行追我，肿其两足，扬兵追我，刀反自伏，明星北斗，却敌万里，追我者亡，觅我者死，牵牛织女，化为江海，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
