    "originalText": "又法太一神人曰，凡欲远行避难若为恶人迫逐危厄之中，出门禹步三咒乃去可以消灾，追我者迷惑五道旋转，到还恶人欲来侵己者，逆而却之，咒曰。东方青毒，南方赤毒，西方白毒，北方黑毒，中央黄毒，五毒之气，今有某甲无道欲来侵，吾被太一神符历行四海，乘风驾云，使有限会，某甲怀恶逆之心，残贼忠良，不肯休止，五毒之气，并力收摄，付与地官，莫令某甲复怀恶心，贼害之意，应时了命，言切千二百等，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
