    "originalText": "夫欲出行先画地为坛房中六尺庭中六尺野外六十步置十二辰位，身居甲地自呼名某乙，今欲出往某处征讨时神保佑於我吉昌三言乾大呼青龙下咒曰，六甲九章，天圆地方，四时五行，青赤白黄，太一为师，日月为先，禹前开道，蚩尤辟兵，青龙侠举，白虎承衡，荧惑先引，辟除不祥，北斗诛罚，除凶去殃，五神导我周游八方，当我者死，向我者亡，欲恶我者，先受其殃，吾受北斗之孙，今日出行，乘青龙出天门入地户，游阴中履华盖去寇贼矛楯刀，戟戟弩，见我摧伏莫敢当禦，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
