    "originalText": "太上老君禁神，三呼三吸以取其真东方青帝木中精、南方赤朱帝雀形、西方白帝白虎神、北方黑帝乘舡行、中央黄帝黄龙声。吾有其禁知天神，盖不自发身归诚，日南施禁火精日北施禁五帝动，经吾三禁，莫敢不来，神道神名，鬼道鬼字，蛊道蛊名，魅道魅字，偷道偷名，贼道贼字，高山腾蛇，下山腾蛇，高山之崎下山之峻或在天上，或在人间，河伯将军，五道脩罗，十二神将，登明君天魁君传送君小吉君腾光君太一君天罡君大冲君功曹君大吉君，速送速送，汝名不得久停，急急如律令",
