    "originalText": "淍（天仇）、九九山（使灵符）淣（法玉籙）涻（一本如此）。右前件取清水半升，以刀子搅之，诵此咒三七遍与小儿饮之，朱书前件籙於小儿膊（作膝）下少时召鬼并来，小儿自见，一一问之即道所作病所作鬼，抄取姓名，发遣如治癫法与过所遣之，如上说也。度符启请神言曰先上香咒笔曰以笔指口鸣六鼓谨请东方青帝老君来下缠吾笔谨请南方赤帝老君来下缠吾笔谨请西方白帝老君来下缠吾笔谨请北方黑帝老君来下缠吾笔谨请中央黄帝老君来下缠吾笔，指天天倾，指地地宁，指鬼鬼死，指人人生，急急一如太上老君律令。请五方水度符言曰谨请东方青龙真气入吾水中谨请南方赤龙真气入吾水中谨请西方白龙真气入吾水中谨请北方黑龙真气入吾水中谨请中央黄龙真气入吾水中谨请五方五龙真气入吾水中，吾水非常之水煮桃作汤吾刀非常之刀七星侠傍，吾口非常之口，内含魁罡水在江中，名曰江水，水在井中名曰井水，水在井中名曰井水，水在吾盆中，名曰清净神水，水在吾口中名日太上老君解秽之水，吾水噀山山崩，噀地地裂，噀人人生，噀鬼鬼灭，急急如律令",
    "originalTextNote": "据人民卫生出版社影印元大德刊本系统影刻电子文本（汉典古籍）过录；底本异体字较多，个别显为刊刻/转录之误者已随文校录，研究者应核原书影像。",
